   143|          Accept: 'application/json',
   144|          'cache-control': 'no-cache',
   145|          pragma: 'no-cache',
   146|        },
   147|      });
   148|      const body = await response.text();
   149|      const contentType = (response.headers.get('content-type') || '').toLowerCase();
   150|
   151|      if (!response.ok) {
   152|        lastError = `HTTP ${response.status}`;
   153|      } else if (!contentType.includes('application/json')) {
   154|        lastError = `invalid content-type ${contentType || 'unknown'}`;
   155|      } else if (isHtmlResponse(body)) {
